import numpy as np

def center_columns(a):
    """Subtract each column's mean from that column; round to 4 decimals."""
    return np.round(a - a.mean(axis=0), 4)

import numpy as np

def pairwise_deltas(x):
    """Return the (n, n) matrix d[i, j] = x[i] - x[j], rounded to 4 dp."""
    x = np.asarray(x, dtype=np.float64)
    return np.round(x[:, None] - x[None, :], 4)
